class AudioPlayer:
    def __init__(self, volume):
        self.volume = volume
    def play(self):
        return f"Playing at volume {self.volume}"

class MP3AudioPlayer(AudioPlayer):
    pass

player = MP3AudioPlayer(50)
print(player.play())
```

